function validate(input) {
  if (input.length !== 8 || !input.every(v => Number.isInteger(v))) return 'Give eight whole-number coordinates.';
  if (input.some(v => v < -10000 || v > 10000)) return 'Each coordinate is between -10^4 and 10^4.';
  const [ax1, ay1, ax2, ay2, bx1, by1, bx2, by2] = input;
  if (ax1 > ax2 || ay1 > ay2) return 'The first rectangle needs ax1 <= ax2 and ay1 <= ay2.';
  if (bx1 > bx2 || by1 > by2) return 'The second rectangle needs bx1 <= bx2 and by1 <= by2.';
  return null;
}

