function computeArea(ax1, ay1, ax2, ay2, bx1, by1, bx2, by2) {
  // Cut the plane along every rectangle edge and add up the grid cells whose lower-left corner is covered.
  const xs = [...new Set([ax1, ax2, bx1, bx2])].sort((p, q) => p - q);
  const ys = [...new Set([ay1, ay2, by1, by2])].sort((p, q) => p - q);
  const inside = (x, y, x1, y1, x2, y2) => x >= x1 && x < x2 && y >= y1 && y < y2;
  let total = 0;
  for (let i = 0; i + 1 < xs.length; i++) {
    for (let j = 0; j + 1 < ys.length; j++) {
      const x = xs[i], y = ys[j];
      if (inside(x, y, ax1, ay1, ax2, ay2) || inside(x, y, bx1, by1, bx2, by2)) total += (xs[i + 1] - x) * (ys[j + 1] - y);
    }
  }
  return total;
}

