function generate(rand, size) {
  const limit = size === 'large' ? 10000 : 6;
  const coord = () => Math.floor(rand() * (2 * limit + 1)) - limit;
  const span = () => {
    const p = coord();
    // Sometimes make the rectangle flat along this axis.
    const q = rand() < 0.1 ? p : coord();
    return p <= q ? [p, q] : [q, p];
  };
  const [ax1, ax2] = span();
  const [ay1, ay2] = span();
  const [bx1, bx2] = span();
  const [by1, by2] = span();
  return [ax1, ay1, ax2, ay2, bx1, by1, bx2, by2];
}
